    23  ProtocolType GreLayer::getGREVersion(uint8_t* greData, size_t greDataLen)
    24  {
    25          if (greDataLen < sizeof(gre_basic_header))
    26                  return UnknownProtocol;
    27
    28          uint8_t version = *(greData+1);
    29          version &= 0x07;
    30          if (version == 0)
    31                  return GREv0;
    32          else if (version == 1)
    33                  return GREv1;
    34          else
    35                  return UnknownProtocol;
    36  }
