    38  uint8_t* GreLayer::getFieldValue(GreField field, bool returnOffsetEvenIfFieldMissing) const
    39  {
    40          uint8_t* ptr = m_Data + sizeof(gre_basic_header);
    41
    42          gre_basic_header* header = (gre_basic_header*)m_Data;
    43
    44          for (int curFieldAsInt = static_cast<int>(GreChecksumOrRouting); curFieldAsInt < 4 /* this value is out of scope of GreField enum values */; ++curFieldAsInt)
    45          {
    46                  const GreField curField = static_cast<GreField>(curFieldAsInt);
    47                  bool curFieldExists = false;
    48
    49                  uint8_t* origPtr = ptr;
    50
    51                  switch (curField)
    52                  {
    53                  case GreChecksumOrRouting:
    54                          if (header->checksumBit == 1 || header->routingBit == 1)
    55                          {
    56                                  curFieldExists = true;
    57                                  ptr += sizeof(uint32_t);
    58                          }
    59                          break;
    60                  case GreKey:
    61                          if (header->keyBit == 1)
    62                          {
    63                                  curFieldExists = true;
    64                                  ptr += sizeof(uint32_t);
    65                          }
    66                          break;
    67                  case GreSeq:
    68                          if (header->sequenceNumBit == 1)
    69                          {
    70                                  curFieldExists = true;
    71                                  ptr += sizeof(uint32_t);
    72                          }
    73                          break;
    74                  case GreAck:
    75                          if (header->ackSequenceNumBit == 1)
    76                          {
    77                                  curFieldExists = true;
    78                                  ptr += sizeof(uint32_t);
    79                          }
    80                          break;
    81                  default: // shouldn't get there
    82                          return nullptr;
    83                  }
    84
    85                  if (field == curField)
    86                  {
    87                          if (curFieldExists || returnOffsetEvenIfFieldMissing)
    88                                  return origPtr;
    89
    90                          return nullptr;
    91                  }
    92          } // for
    93
    94          return nullptr;
    95  }
